// Distributed RPC Tracing Context Propagation in Go
func InjectTraceContext(ctx context.Context, req *http.Request) {
    otel.GetTextMapPropagator().Inject(ctx, propagation.HeaderCarrier(req.Header))
    req.Header.Set("X-Service-Source", "order-service")
    req.Header.Set("X-Client-Timeout-Budget-Ms", "1500")
}

public record OrderId(UUID value) {}

public class OrderAggregate {
    private final OrderId id;
    private OrderStatus status;
    private final List<OrderLineItem> items;

    public void cancel(String reason) {
        if (status == OrderStatus.SHIPPED) {
            throw new IllegalStateException("Cannot cancel an order that has already shipped.");
        }
        this.status = OrderStatus.CANCELLED;
        DomainEvents.publish(new OrderCancelledEvent(this.id, reason, Instant.now()));
    }
}

syntax = "proto3";
package billing.v1;

message ChargePaymentRequest {
  string transaction_id = 1;
  int64 amount_cents = 2;
  string currency_code = 3;
  reserved 4;
  reserved "payment_token";
  string idempotency_key = 5;
}

service PaymentService {
  rpc ChargePayment (ChargePaymentRequest) returns (ChargePaymentResponse);
}

@Bean
public RouteLocator customRouteLocator(RouteLocatorBuilder builder) {
    return builder.routes()
        .route("order_service", r -> r.path("/api/v1/orders/**")
            .filters(f -> f.stripPrefix(2)
                .addRequestHeader("X-Gateway-Processed", "true")
                .requestRateLimiter(c -> c.setRateLimiter(redisRateLimiter()))
                .circuitBreaker(c -> c.setName("orderCircuit").setFallbackUri("forward:/fallback")))
            .uri("lb://ORDER-SERVICE"))
        .build();
}

@Transactional
public void compensateInventoryReservation(UUID orderId) {
    if (compensationHistoryRepository.existsByOrderId(orderId)) {
        return; // Idempotency check: already compensated
    }
    inventoryRepository.releaseReservedStock(orderId);
    compensationHistoryRepository.save(new CompensationRecord(orderId, Instant.now()));
}

