@CircuitBreaker(name = "paymentService", fallbackMethod = "queueForOfflineReview")
public PaymentResult chargeCard(PaymentRequest request) {
    return restTemplate.postForObject("/charges", request, PaymentResult.class);
}

// Fallback executed in 1ms when circuit is OPEN
public PaymentResult queueForOfflineReview(PaymentRequest req, Throwable ex) {
    offlineQueue.publish(req);
    return PaymentResult.acceptedPendingReview();
}

func callDownstream(ctx context.Context, url string) (*http.Response, error) {
    tr := otel.Tracer("order-service")
    ctx, span := tr.Start(ctx, "callDownstream", trace.WithSpanKind(trace.SpanKindClient))
    defer span.End()

    req, _ := http.NewRequestWithContext(ctx, "GET", url, nil)
    // Injects W3C traceparent header into HTTP request
    otel.GetTextMapPropagator().Inject(ctx, propagation.HeaderCarrier(req.Header))
    return http.DefaultClient.Do(req)
}

@Component
public class CorrelationIdFilter extends OncePerRequestFilter {
    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain)
            throws ServletException, IOException {
        String corrId = req.getHeader("X-Correlation-ID");
        if (corrId == null || corrId.isBlank()) {
            corrId = UUID.randomUUID().toString();
        }
        MDC.put("correlationId", corrId);
        res.setHeader("X-Correlation-ID", corrId);
        try {
            chain.doFilter(req, res);
        } finally {
            MDC.clear(); // Always clear thread-local to prevent leaks!
        }
    }
}
